test('dashboard returns top 3 customers by due amount', () => {
  const invoices = [];

  // Create invoices for multiple customers
  for (let i = 1; i <= 5; i++) {
    const r = createInvoice({
      customerId: `C-00${i}`,
      issueDate: '2024-01-15',
      lines: [{ sku: 'DEV-HOUR', qty: i, discountPercent: 0 }],
    });

    assert.equal(r.ok, true);
    const issued = issueInvoice(r.value, invoices.map((inv) => inv.number));
    assert.equal(issued.ok, true);
    invoices.push(issued.value);
  }

  const result = dashboard(invoices, '2024-02-01');

  assert.equal(result.topCustomers.length, 3);
  // Should be sorted highest to lowest
  for (let i = 1; i < result.topCustomers.length; i++) {
    assert(result.topCustomers[i - 1].due >= result.topCustomers[i].due);
  }
});

test('dashboard top customers only includes issued/partially_paid', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r1.ok, true);
  assert.equal(r2.ok, true);

  const issued = issueInvoice(r1.value, []);
  assert.equal(issued.ok, true);

  const paid = recordPayment(issueInvoice(r2.value, ['INV-2024-0001']).value, {
    amount: 200000,
    date: '2024-01-20',
  });
  assert.equal(paid.ok, true);

  const invoices = [issued.value, paid.value];
  const result = dashboard(invoices, '2024-02-01');

  // Only C-001 from the issued invoice should be in top customers
  // The paid invoice's balance is 0, so it shouldn't count toward due amount
  assert.equal(result.topCustomers.length, 1);
  assert.equal(result.topCustomers[0].customerId, 'C-001');
});

test('dashboard with multiple payments on same customer', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  let issued = issueInvoice(r.value, []);
  assert.equal(issued.ok, true);

  let invoice = issued.value;
  invoice = recordPayment(invoice, { amount: 30000, date: '2024-01-20' }).value;
  invoice = recordPayment(invoice, { amount: 20000, date: '2024-01-25' }).value;

  const result = dashboard([invoice], '2024-02-01');

  // Customer should appear in top customers with remaining balance
  assert.equal(result.topCustomers.length, 1);
  assert.equal(result.topCustomers[0].customerId, 'C-001');
  assert(result.topCustomers[0].due > 0);
});

