  // Due date: 2024-02-14
  // Report date: 2024-02-24 (10 days overdue)
  // Fee = 104950 * 0.0004 * 10 = 419.8 = 420 cents (rounded)
  const fee = lateFee(issued.value, '2024-02-24');
  assert.equal(fee, 420);
});

